// Normalizes either Gemini or Grok response shape into one flat object
const raw = $input.item.json;
let text;
if (raw.candidates) {
  text = raw.candidates[0].content.parts[0].text;
} else if (raw.choices) {
  text = raw.choices[0].message.content;
} else {
  text = JSON.stringify(raw);
}
text = text.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { main_topic: 'Uncategorized', sub_topic: null, keywords: [], content_type: 'announcement', cta_type: 'none', has_promotion: false, promotion_details: null };
}

// Normalize topic casing so 'business profile' and 'Business Profile'
// collapse into one trend bucket instead of splitting WF-03's GROUP BY.
function titleCase(str) {
  if (!str || typeof str !== 'string') return str;
  return str.trim().toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
}
parsed.main_topic = titleCase(parsed.main_topic);
parsed.sub_topic = titleCase(parsed.sub_topic);

return { json: parsed };
